  const numeroPedido = new URLSearchParams(window.location.search).get('numero');
  const NOMES_FORNECEDOR={cj:'CJ Dropshipping',buckydrop:'BuckyDrop'};
  const NOMES_ESTADO={pago:'Pago',novo:'Aguarda pagamento',processando:'Processando',enviado_ao_agente:'Enviado ao agente de carga',a_caminho:'A caminho',a_caminho_destino_final:'A caminho do destino final',entregue:'Entregue',cancelado:'Cancelado'};
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function linhaFornecedor(d,p){const chave=d.fornecedor;return `<div class="grade-form-admin" style="margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid var(--linha)"><div class="campo-formulario"><label>Fornecedor</label><input value="${esc(NOMES_FORNECEDOR[chave]||chave)}" disabled></div><div class="campo-formulario"><label>Nº de pedido no fornecedor</label><input value="${esc(d.id_pedido_fornecedor||'')}" disabled></div><div class="campo-formulario"><label>Rastreio 1</label><input id="rastreio1-${chave}" value="${esc(d.rastreio1||'')}"></div>${p.rotaEnvio==='agente_de_carga'?`<div class="campo-formulario"><label>Rastreio 2</label><input id="rastreio2-${chave}" value="${esc(d.rastreio2||'')}"></div>`:''}<div class="campo-formulario"><label>Estado</label><select id="estado-${chave}">${['processando','enviado_ao_agente','a_caminho','a_caminho_destino_final','entregue'].map(v=>`<option value="${v}" ${d.estado===v?'selected':''}>${NOMES_ESTADO[v]}</option>`).join('')}</select></div></div><button class="btn btn-secundario" onclick="guardarFornecedor('${chave}')">Guardar tracking</button>${d.estado_envio!=='enviado'?` <button class="btn btn-primario" onclick="enviarFornecedor('${chave}')">Enviar ao fornecedor</button>`:''}`}
  async function carregarPedido(){try{const p=await apiFetch('/pedidos/'+encodeURIComponent(numeroPedido));document.title=`Pedido ${p.numeroPedido} — Admin Lúmina`;document.getElementById('pdd-titulo').textContent=`Encomenda ${p.numeroPedido}`;document.getElementById('pdd-info').innerHTML=`${esc(p.moradaEntrega.linha1)}, ${esc(p.moradaEntrega.cidade)} (${esc(p.moradaEntrega.pais)}) · Moeda: ${esc(p.moeda)} · Rota: ${p.rotaEnvio==='agente_de_carga'?'via agente de carga':'direta'} · Estado: <span class="badge-status">${esc(NOMES_ESTADO[p.estado]||p.estado)}</span>`;document.getElementById('pdd-itens').innerHTML=p.itens.map(i=>`<div class="linha-resumo"><span>${esc(i.nome_produto)} ×${i.quantidade}</span><span>${Number(i.preco_unitario_eur*i.quantidade).toFixed(2)} €</span></div>`).join('')+`<div class="linha-resumo total"><span>Total</span><span>${Number(p.totalEUR).toFixed(2)} €</span></div>`;const pg=p.pagamento||{};document.getElementById('pdd-pagamento').innerHTML=`Método: <b>${esc(pg.metodo==='manual'?'Manual':(pg.metodo||'—'))}</b> · Estado: <b>${esc(pg.estado||'sem pagamento')}</b>${pg.nota?' · '+esc(pg.nota):''}`;document.getElementById('pdd-btn-pago').style.display=(pg.estado==='pendente'&&['aguarda_pagamento','comprovativo_enviado'].includes(p.estado))?'inline-block':'none';document.getElementById('pdd-estado').innerHTML=['novo','pago','processando','enviado_ao_agente','a_caminho','a_caminho_destino_final','entregue','cancelado'].map(v=>`<option value="${v}" ${p.estado===v?'selected':''}>${NOMES_ESTADO[v]||v}</option>`).join('');const fs=p.fornecedores||[];document.getElementById('pdd-fornecedores').innerHTML=fs.length?fs.map(d=>linhaFornecedor(d,p)).join('<br>'):'<p style="font-size:13.5px;color:#8A7A70">Ainda sem sub-pedido criado.</p>';}catch(e){document.getElementById('pdd-erro').textContent='Erro ao carregar pedido: '+e.message;document.getElementById('pdd-erro').style.display='block'}}
  async function guardarFornecedor(chave){const corpo={rastreio1:document.getElementById('rastreio1-'+chave)?.value.trim()||null,estado:document.getElementById('estado-'+chave)?.value};const r2=document.getElementById('rastreio2-'+chave);if(r2)corpo.rastreio2=r2.value.trim()||null;try{await apiFetch(`/pedidos/${encodeURIComponent(numeroPedido)}/fornecedor/${chave}`,{method:'PUT',body:JSON.stringify(corpo)});await carregarPedido()}catch(e){alert(e.message)}}
  async function marcarPagoPedido(){const pg=await apiFetch('/pedidos/'+encodeURIComponent(numeroPedido));const valor=prompt('Valor recebido na moeda '+(pg.pagamento?.moeda||'EUR')+':',String(pg.pagamento?.valor_esperado||''));if(valor===null)return;const referencia=prompt('Referência bancária (opcional):','')||'';const nota=prompt('Nota de reconciliação (obrigatória se existir diferença):','')||'';try{await apiFetch('/pagamentos/admin/'+encodeURIComponent(numeroPedido)+'/confirmar',{method:'POST',body:JSON.stringify({valorRecebido:Number(valor),referencia,nota})});await carregarPedido()}catch(e){alert(e.message)}}
  async function enviarFornecedor(chave){if(!confirm('Enviar esta encomenda real ao fornecedor? A ação pode gerar custos e não deve ser repetida manualmente se estiver em curso.'))return;try{const r=await apiFetch('/operacoes/admin/pedidos/'+encodeURIComponent(numeroPedido)+'/enviar-fornecedor/'+encodeURIComponent(chave),{method:'POST',body:JSON.stringify({})});alert(r.jaEnviado?'Esta encomenda já estava enviada.':'Encomenda enviada ao fornecedor.');await carregarPedido()}catch(e){alert(e.message||'Falha ao enviar ao fornecedor.')}}
  async function guardarEstadoPedido(){try{await apiFetch('/pedidos/'+encodeURIComponent(numeroPedido)+'/estado',{method:'PUT',body:JSON.stringify({estado:document.getElementById('pdd-estado').value})});await carregarPedido()}catch(e){alert(e.message)}}
  if(numeroPedido)carregarPedido();else{document.getElementById('pdd-erro').textContent='Nenhum pedido indicado na URL.';document.getElementById('pdd-erro').style.display='block'}
